83	\begin{definition}[Universal constants of the scenario]
84	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
85	\lean{IPhO2026.Problem1.B2.particleMass}
86	\lean{IPhO2026.Problem1.B2.hbar}
