121	\begin{definition}[The unbound-case value $\mu = 15/2$]
122	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu}
123	\lean{IPhO2026.Problem1.B2.unboundMu}
124	The value $\mu = 15/2$ of subquestion B.2 (the unbound, hyperbolic case).
125	\end{definition}
