137	\subsection*{Scattering data and governing laws}
138	
139	\begin{definition}[Two-body Coulomb scattering data]
140	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData}
141	\lean{IPhO2026.Problem1.B2.CoulombScatteringData}
142	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:Plane, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu}
143	The B.1-style two-body record of the isolated, classical, non-relativistic
144	electron--positron pair with purely electrostatic interaction, with the
145	two-body-to-one-body reduction encoded.  Data: the CM-frame relative
146	curve $\mathrm{sep} : \mathbb{R} \to \mathrm{Plane}$
147	($r_{e+}(t) - r_{e-}(t)$, m), initial data ($r_0 = 100\,a_0$, antiparallel
148	CM velocities $\pm v_0$ perpendicular to the separation with the Fig.-1b
149	orientation $\mathrm{perp}\ \mathrm{sep0}\ v_0 = r_0 v_0$, relative speed
150	$2v_0$, per-particle angular momentum $\mu\hbar$ certified by
151	$m v_0 (r_0/2) = \mu \hbar$), the reduced mass $m_{\mathrm{red}} = m/2$,
152	the total angular momentum $L = 2\mu\hbar$ and total energy $E$, and a
153	continuous polar angle.  Governing-law fields: Coulomb's law for the
154	conserved energy, Newton's equation for the reduced particle under the
155	attractive Coulomb force, angular-momentum conservation
156	$\mathrm{perp}(\mathrm{sep}, \dot{\mathrm{sep}}) = L/m_{\mathrm{red}}$, the
157	radial-energy identity multiplied out by $r^2 > 0$, the turning point at
158	$t = 0$ (radial speed zero), twice-continuous-differentiable regularity,
159	and $\mathrm{sep}\,t \neq 0$ for all $t$.  No orbit shape, asymptotic
160	velocity, or deflection angle appears among the fields; those are
161	conclusion-side.
162	\end{definition}
163	
164	\begin{lemma}[Initial separation is positive]
165	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:initial_separation_pos}
166	\lean{IPhO2026.Problem1.B2.CoulombScatteringData.initial_separation_pos}
167	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime}
168	The Fig.-1b readout satisfies $0 < r_0$.
169	\end{lemma}
170	\begin{proof}
171	Rewrite $r_0 = 100\,a_0$; the product $100 \cdot a_0$ is positive since
172	$a_0 > 0$.
173	\end{proof}
174	
175	\begin{lemma}[Total angular momentum value]
176	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_angular_momentum_value}
177	\lean{IPhO2026.Problem1.B2.CoulombScatteringData.total_angular_momentum_value}
178	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu}
179	The total angular momentum has the value $L = 2\,(\mu\hbar) = 15\hbar$ for
180	$\mu = 15/2$.
181	\end{lemma}
182	\begin{proof}
183	Rewrite $L$ by its defining field as twice the per-particle contribution,
184	then substitute the given identity $m v_0 (r_0/2) = \mu\hbar$.
185	\end{proof}
186	
187	\begin{definition}[Turning-point quadratic]
188	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic}
189	\lean{IPhO2026.Problem1.B2.CoulombScatteringData.turningQuadratic}
190	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
191	The effective radial quadratic
192	$Q(r) = E r^2 + k e^2 r - L^2/(2 m_{\mathrm{red}})$: along the trajectory
193	the radial-energy identity gives
194	$Q(r) = \tfrac{1}{2} m_{\mathrm{red}}\, \dot r^{\,2} r^2$, so $Q(r) = 0$
195	exactly at turning points.
196	\end{definition}
197	
198	\begin{lemma}[Periapsis at the initial separation]
199	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic_periapsis}
200	\lean{IPhO2026.Problem1.B2.CoulombScatteringData.turningQuadratic_periapsis}
201	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData}
202	The initial separation is a turning point (the periapsis of the unbound
203	orbit): $Q(r_0) = 0$.
204	\end{lemma}
205	\begin{proof}
206	Evaluate the radial-energy law at $t = 0$: $\mathrm{sep}\,0 = \mathrm{sep0}$
207	has norm $r_0$ and the radial speed vanishes there, so the right-hand side
208	is zero; unfold $Q$ and read off the equality.
209	\end{proof}
210	
211	\begin{definition}[Semilatus rectum]
212	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:semilatusRectum}
213	\lean{IPhO2026.Problem1.B2.CoulombScatteringData.semilatusRectum}
214	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
215	The semilatus rectum $p = L^2/(m_{\mathrm{red}}\,k\,e^2)$ of the reduced
216	one-body problem (m): the geometric scale of the conic in Hint 2.
217	\end{definition}
218	
219	\begin{definition}[Squared eccentricity]
220	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq}
221	\lean{IPhO2026.Problem1.B2.CoulombScatteringData.eccentricitySq}
222	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
223	The dimensionless squared eccentricity
224	$\varepsilon^2 = 1 + 2 E L^2/(m_{\mathrm{red}} (k e^2)^2)$; for equal
225	masses $m_{\mathrm{red}} = m/2$ reconciles the denominator with the page's
226	Hint-1 form $\varepsilon^2 = 1 + 4 E L^2/(k^2 e^4 m)$.
227	\end{definition}
228	
229	\subsection*{Unboundness and conic bridges}
230	
231	\begin{theorem}[Positivity of the total energy (unboundness)]
232	\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos}
233	\lean{IPhO2026.Problem1.B2.total_energy_pos}
234	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:IsAngularMomentumFactor}
235	For $\mu = 15/2$ the total energy is the Fig.-1b value
236	$E = \mu^2/2500 - 1/200$ in units of $\hbar^2/(m a_0^2)$, i.e.\
237	$E = 7/400 > 0$: the pair is unbound (hyperbolic scattering).
238	\end{theorem}
239	\begin{proof}
240	Evaluate the energy law at $t = 0$: by the transverse configuration the
241	energy is kinetic plus Coulomb,
242	$E = 2\cdot\tfrac12 m v_0^2 - k e^2/r_0$; eliminate $v_0$ via
243	$m v_0 (r_0/2) = \mu\hbar$ with $r_0 = 100\,a_0$ and the Bohr-radius identity
244	$a_0 = \hbar^2/(k m e^2)$, giving
245	$E = (\mu^2/2500 - 1/200)\,\hbar^2/(m a_0^2) = 7/400 > 0$ in those units.
246	Pure algebra; no angle content.
247	\end{proof}
248	
249	\begin{lemma}[Eccentricity exceeds one]
250	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_gt_one}
251	\lean{IPhO2026.Problem1.B2.eccentricity_gt_one}
252	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq, thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_angular_momentum_value, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime}
253	At $\mu = 15/2$ the squared eccentricity strictly exceeds $1$: the conic is
254	a hyperbola, not an ellipse.
255	\end{lemma}
256	\begin{proof}
257	The added Hint-1 term $2 E L^2/(m_{\mathrm{red}} (k e^2)^2)$ is a quotient
258	of positive quantities: $E > 0$
259	(\cref{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos}),
260	$m_{\mathrm{red}} = m/2 > 0$, $L = 15\hbar \neq 0$, and $k, e > 0$; hence
261	$\varepsilon^2 = 1 + (\text{positive}) > 1$.
262	\end{proof}
263	
264	\begin{theorem}[Eccentricity value (Hint 1, derivable)]
265	\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_sq_eq}
266	\lean{IPhO2026.Problem1.B2.eccentricity_sq_eq}
267	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:IsAngularMomentumFactor}
268	Evaluation of the official Hint-1 formula for this scenario:
269	$\varepsilon^2 = 49/4$ (so $\varepsilon = 7/2 > 1$).  This is the
270	page's first hint recorded as a \emph{derivable bridge lemma}, not an
271	assumed law; it is conclusion-free of angle data.  (Iter-014 repair: the
272	previous claim $\varepsilon^2 = 67/4$ is arithmetically false as a
273	statement of this derivation --- with the total energy
274	$E = +\,k e^2/(80 a_0)$ of the official solution the Hint-1 formula
275	evaluates to $45/4 + 1 = 49/4$; the false $67/4$ is the iter-005 $E < 0$
276	elliptic branch's value.)
277	\end{theorem}
278	\begin{proof}
279	From the same laws as
280	\cref{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos}:
281	substitute $E = +\,k e^2/(80 a_0) = 7/400$ (in units
282	$\hbar^2/(m a_0^2)$), $L = 15\hbar$, $m_{\mathrm{red}} = m/2$, and the
283	Bohr-radius identity into $1 + 2 E L^2/(m_{\mathrm{red}}(k e^2)^2) =
284	1 + 4 \cdot \tfrac{4 k e^2 \cdot (15\hbar^2)}{80 a_0\, m (k e^2)^2}$
285	(the official numerator $\tfrac{4 k e^2\,(15\hbar^2)}{80 a_0\,m(ke^2)^2}$);
286	the units cancel and the rational arithmetic gives
287	$1 + 45/4 = 49/4$.
288	\end{proof}
289	
290	\begin{theorem}[Polar conic form of the orbit (Hint 2, derivable)]
291	\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:orbit_eq_conic}
292	\lean{IPhO2026.Problem1.B2.orbit_eq_conic}
293	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:semilatusRectum, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic_periapsis, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_gt_one, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData}
294	The page's second hint as a derivable bridge: the trajectory
295	$r = \lVert \mathrm{sep}\,t \rVert$ as a function of its own polar angle
296	$\theta(t)$ is a conic -- there exist $\varepsilon = \sqrt{\varepsilon^2} > 1$
297	and a symmetry-axis direction $\theta_0$ (a priori unknown) such that for
298	all $t$, $\varepsilon\cos(\theta(t) - \theta_0) - 1 > 0$ and
299	$r = p/(\varepsilon\cos(\theta(t) - \theta_0) - 1)$ (the periapsis branch
300	of the page's form $r = a/(1 - \varepsilon\cos\theta)$ up to the axis
301	orientation).
302	\end{theorem}
303	\begin{proof}
304	Set $u = 1/r$; angular-momentum conservation
305	$\dot\theta = L/(m_{\mathrm{red}} r^2)$
306	turns Newton's radial equation into Binet's linear equation
307	$u'' + u = m_{\mathrm{red}} k e^2/L^2$, whose solution with the periapsis
308	initial condition (radial speed zero at $t = 0$,
309	\cref{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic_periapsis})
310	is $u = p^{-1}(\varepsilon\cos(\theta - \theta_0) - 1)$ with
311	$p = L^2/(m_{\mathrm{red}} k e^2)$ and $\varepsilon$ matching
312	\cref{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq};
313	the unboundness $\varepsilon > 1$
314	(\cref{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_gt_one})
315	selects the physical branch with positive denominator.
316	\end{proof}
