318	\subsection*{Asymptotic relative velocity}
319	
320	\begin{definition}[Initial line of motion of the positron]
321	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:initialDirection}
322	\lean{IPhO2026.Problem1.B2.initialDirection}
323	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:Plane}
324	The initial line of motion of $e^+$: the unit vector
325	$\hat u_0 = \lVert v_0 \rVert^{-1} v_0$ along the initial positron velocity
326	(Fig. 1b) -- the reference direction of the asked angle.
327	\end{definition}
328	
329	\begin{definition}[Candidate relative-velocity vector]
330	\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:RelativeVelocityVector}
331	\lean{IPhO2026.Problem1.B2.RelativeVelocityVector}
332	\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:Plane}
333	A planar vector record (single plane-vector field, m/s): plain data to
334	which the predicate
335	\cref{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:IsAsymptoticRelativeVelocity}
336	then assigns the physical role of $u_\infty$.
337	\end{definition}
338	
